ValidationRule.errorConditionFormula:
AND ( RecordType.DeveloperName = "Sales_Offers_Request" , /*Sales Offers Service Request*/ ISPICKVAL ( Type , "Campaign" ), NOT ( $Profile.Name = "System Administrator"), /*System Administrator*/ NOT ( $Profile.Name = "Qantas System Administrator"), NOT ( $Profile.Name = "Qantas System Admin - Freight"), NOT ( $Profile.Name = "Qantas System Admin - QCC"), NOT ( $Profile.Name = "Qantas System Admin - SND"), NOT ( $UserRole.Id = $Label.QF_Support_QIC_Member), /*QF-Support-Agency Support-QAC*/
OR( Presence_of_Frequent_Flyer_Information__c >=1 , ISBLANK ( Number_of_Frequent_Flyer_Request__c ) )
)
